class LigneCommande:
    def __init__(self, produit, quantite):
        if quantite <= 0:
            raise ValueError("La quantité doit être supérieure à zéro.")

        self.produit = produit
        self.quantite = quantite

    def sous_total_centimes(self):
        return self.produit.prix_pour(self.quantite)

class Commande:
    def __init__(self):
        self.lignes = []

    def ajouter(self, produit, quantite):
        ligne = LigneCommande(produit, quantite)
        self.lignes.append(ligne)

    def total_centimes(self):
        return sum(
            ligne.sous_total_centimes()
            for ligne in self.lignes
        )

commande = Commande()
commande.ajouter(Pizza("Margherita", 850, "moyenne"), 2)
commande.ajouter(Boisson("Limonade", 350, 330), 1)

print(commande.total_centimes())  # 2050

