def produit_depuis_donnees(donnees):
    type_produit = donnees["type"]
    nom = donnees["nom"]
    prix_centimes = donnees["prix_centimes"]

    if type_produit == "pizza":
        return Pizza(
            nom,
            prix_centimes,
            donnees["taille"],
        )
    elif type_produit == "boisson":
        return Boisson(
            nom,
            prix_centimes,
            donnees["volume_ml"],
        )
    else:
        raise ValueError(f"Type de produit inconnu : {type_produit}")

class LigneCommande:
    # Le constructeur et sous_total_centimes restent ceux de la section 2.

    def vers_donnees(self):
        return {
            "produit": self.produit.vers_donnees(),
            "quantite": self.quantite,
        }

class Commande:
    # Le constructeur, ajouter et total_centimes restent ceux de la section 3.

    def vers_donnees(self):
        return {
            "lignes": [
                ligne.vers_donnees()
                for ligne in self.lignes
            ]
        }

    @classmethod
    def depuis_donnees(cls, donnees):
        commande = cls()

        for ligne_donnees in donnees["lignes"]:
            produit = produit_depuis_donnees(
                ligne_donnees["produit"]
            )
            commande.ajouter(
                produit,
                ligne_donnees["quantite"],
            )

        return commande
